import{_ as r,l as p,o as a,c as l,v as t,p as n,x as o,d as h,i as c,S as s}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Expert Choice 论文","description":"","frontmatter":{"title":"Expert Choice 论文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/expert-choice-paper.md","filePath":"llm/expert-choice-paper.md","lastUpdated":1789023840000}'),d={name:"llm/expert-choice-paper.md"};function u(m,e,E,x,k,_){const i=p("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="expert-choice-论文" tabindex="-1">Expert Choice 论文 <a class="header-anchor" href="#expert-choice-论文" aria-label="Permalink to &quot;Expert Choice 论文&quot;">​</a></h1><div class="epigraph"><p>让每个专家在自己的容量内挑选 token，专家维负载天然齐平；有的 token 会被抢多次，有的一次都轮不到。</p><footer>—— Zhou et al., Mixture-of-Experts with Expert Choice Routing, NeurIPS 2022</footer></div><p><a href="/llm/fedus-switch">Switch 原文</a> 是 token-choice：\\(k=1\\) 时每行取 argmax，再用容量因子 drop。Zhou、Lei、Liu 等人把矩阵转过来：<strong>每列（专家）取 top-\\(C\\)</strong>。主干 <a href="/llm/moe-expert-choice">Expert-choice 路由</a> 已写机制；本篇对照论文主张与实验边界，并提醒自回归解码的不一致是原文就必须面对的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Token-choice 的均衡靠辅助损失，失败则专家饿死或过载 drop。作者问：若约束直接写在专家配额上，还能否提高专家利用率与下游质量？分数矩阵 \\(S\\in\\mathbb{R}^{T\\times N}\\)，列上 top-\\(C\\)、\\(C\\) 由目标等价负载决定，则每个专家恰好 \\(C\\) 个 token。</p><p>副效应：行和不再恒等于 \\(k\\)。过分配与零覆盖是论文必须处理的对象，不是实现 bug。</p><h3 id="训练可见整段" tabindex="-1">训练可见整段 \\(T\\) <a class="header-anchor" href="#训练可见整段" aria-label="Permalink to &quot;训练可见整段 $T$&quot;">​</a></h3><p>编码器或训练期整句可见时，列 top 合法。逐步解码没有未来行。论文语境含预训练与理解任务；把它当 LLM decode 默认路由，需要近似，主干课已写。<span class="marginnote">作者名单以 Yanqi Zhou、Tao Lei、Hanxiao Liu 等为主，Google 线。引用用论文题名，不要用内部别名当文献。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="列上-top-与回退" tabindex="-1">列上 top-\\(C\\) 与回退 <a class="header-anchor" href="#列上-top-与回退" aria-label="Permalink to &quot;列上 top-$C$ 与回退&quot;">​</a></h3><p>对 \\(S\\) 每列取 top-\\(C\\)，只在选中位置做专家 FFN。负载统计变为近乎常数，辅助损失可以减弱。对零覆盖 token 的回退（残差或强制分配）影响质量，属于实验选择。评测对比同参数 / 同计算下的 token-choice。覆盖率与下游应同时报，否则「利用率上升」只是负载直方图好看。</p>',11)),(a(),n(s,null,{default:o(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%88%86%E6%95%B0%20T%20%E4%B9%98%20N%22%5D%20--%3E%20COL%5B%22%E6%AF%8F%E5%88%97%20top-C%22%5D%0A%20%20COL%20--%3E%20BAL%5B%22%E4%B8%93%E5%AE%B6%E8%B4%9F%E8%BD%BD%E9%BD%90%22%5D%0A%20%20COL%20--%3E%20ROW%5B%22token%20%E8%BF%87%E5%88%86%E9%85%8D%E6%88%96%E9%9B%B6%E8%A6%86%E7%9B%96%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>竞争从「token 抢热专家」改为「专家抢高分 token」。利用率上升是直接推论；专业化方向取决于分数是否分列归一。论文用实验支持质量，而不是只报负载直方图。读者应同时看下游与覆盖率——原文若偏重利用率，工程复现仍要补覆盖日志。</p><p>与 Switch 的 drop 伤害对象不同：Switch 丢过载门口的人；EC 丢无人认领的人。长尾语言风险在论文的通用语料平均里可能被稀释。</p><p><span class="marginnote">容量 \\(C\\) 在 EC 里是吃满配额，在 Switch 里是上限。同一符号，对照时必须说清等式还是不等式。</span></p><h3 id="在对照链中的位置" tabindex="-1">在对照链中的位置 <a class="header-anchor" href="#在对照链中的位置" aria-label="Permalink to &quot;在对照链中的位置&quot;">​</a></h3><p>下一篇 z-loss 对照稳定训练；EC 本身减轻均衡损失，但不自动解决 logit 爆炸。不要把「不用辅助损失」写成 EC 的全部贡献——那是负载几何，不是数值尺度。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>小 \\(T\\)（微 batch）时 top-\\(C\\) 统计崩溃。packing 跨样本会让专家跨句抢 token，论文设定若为单句 / 规范 batch，搬到 LLM packing 必须加掩码。生成任务要用 token-choice 近似，训练–推理差是一等限制。</p><p>NeurIPS 2022 的数字绑定他们的模型与数据。Mixtral / DeepSeek 产品默认仍是 token-choice，说明工业默认并未翻转。对照价值是指出负载约束可以写在另一条轴上。</p><p><span class="marginnote">题名 <em>Mixture-of-Experts with Expert Choice Routing</em>。会议 NeurIPS 2022。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原文把路由改为专家侧 top-\\(C\\)，专家负载齐、token 覆盖不齐。</li><li>针对 token-choice + 辅助损失 + drop 的配方提出替代几何。</li><li>自回归 decode 不能原样执行列选择。</li><li>利用率不是唯一验收；须看零覆盖与下游。</li><li>出处：Zhou 等，NeurIPS 2022。</li></ul>',12))])}const b=r(d,[["render",u]]);export{f as __pageData,b as default};
